'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Hexagon tile map: Lagos | Oyo | Ondo",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "background": null,
  "params": [
    {
      "name": "hexSize",
      "value": 1040
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "datum.state_name === ''Lagos'' ? 0 : (datum.state_name === ''Oyo'' ? 8.5 : 15.5)",
      "as": "xoff"
    },
    {
      "calculate": "(datum.tile_col - 1) + datum.xoff + ((datum.tile_row % 2) === 0 ? 0.5 : 0)",
      "as": "gx"
    },
    {
      "calculate": "(datum.tile_row - 1) * 0.866",
      "as": "gy"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "point",
        "shape": "M0,-1L0.866,-0.5L0.866,0.5L0,1L-0.866,0.5L-0.866,-0.5Z",
        "filled": true,
        "size": {
          "expr": "hexSize"
        },
        "strokeWidth": 2,
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "gx",
          "type": "quantitative",
          "scale": {
            "domain": [
              -0.7,
              20.7
            ]
          },
          "axis": null
        },
        "y": {
          "field": "gy",
          "type": "quantitative",
          "scale": {
            "domain": [
              -1.7,
              6.4
            ],
            "reverse": true
          },
          "axis": null
        },
        "color": {
          "condition": {
            "test": "datum[''Tile In Scope''] === 0",
            "value": "#E6ECEF"
          },
          "field": "Tile Action",
          "type": "nominal",
          "legend": null,
          "scale": {
            "domain": [
              "Add public clinics",
              "Contract private clinics",
              "No action now"
            ],
            "range": [
              "#B4281E",
              "#E8B4AF",
              "#C9D3D8"
            ]
          }
        },
        "stroke": {
          "condition": {
            "test": "datum[''Tile Action''] === ''Contract private clinics''",
            "value": "#B4281E"
          },
          "value": "#FFFFFF"
        },
        "opacity": {
          "condition": {
            "test": "datum[''__selected__''] === ''off''",
            "value": 0.4
          },
          "value": 1
        },
        "tooltip": [
          {
            "field": "lga_name",
            "type": "nominal",
            "title": "LGA"
          },
          {
            "field": "state_name",
            "type": "nominal",
            "title": "State"
          },
          {
            "field": "Tile Action",
            "type": "nominal",
            "title": "Recommended action"
          },
          {
            "field": "Tile People Per Clinic",
            "type": "quantitative",
            "title": "People per public clinic",
            "format": ",.0f"
          },
          {
            "field": "Tile Clinics Needed",
            "type": "quantitative",
            "title": "Public clinics needed",
            "format": ",.0f"
          },
          {
            "field": "Tile Confidence",
            "type": "nominal",
            "title": "Confidence"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "font": "Segoe UI",
        "fontSize": 8.5,
        "fontWeight": "bold",
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "gx",
          "type": "quantitative",
          "scale": {
            "domain": [
              -0.7,
              20.7
            ]
          },
          "axis": null
        },
        "y": {
          "field": "gy",
          "type": "quantitative",
          "scale": {
            "domain": [
              -1.7,
              6.4
            ],
            "reverse": true
          },
          "axis": null
        },
        "text": {
          "field": "tile_label",
          "type": "nominal"
        },
        "color": {
          "condition": [
            {
              "test": "datum[''Tile In Scope''] === 0",
              "value": "#9AA9B1"
            },
            {
              "test": "datum[''Tile Action''] === ''Add public clinics''",
              "value": "#FFFFFF"
            },
            {
              "test": "datum[''Tile Action''] === ''Contract private clinics''",
              "value": "#7A1F18"
            }
          ],
          "value": "#33474F"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ],
          "groupby": [
            "state_name"
          ]
        },
        {
          "calculate": "datum.state_name === ''Lagos'' ? -0.45 : (datum.state_name === ''Oyo'' ? 8.05 : 15.05)",
          "as": "x"
        },
        {
          "calculate": "datum.n + '' LGAs''",
          "as": "t"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "font": "Segoe UI",
        "fontSize": 10,
        "color": "#51656F"
      },
      "encoding": {
        "x": {
          "field": "x",
          "type": "quantitative",
          "scale": {
            "domain": [
              -0.7,
              20.7
            ]
          },
          "axis": null
        },
        "y": {
          "value": 16
        },
        "text": {
          "field": "t",
          "type": "nominal"
        }
      }
    },
    {
      "data": {
        "values": [
          {
            "x": -0.45,
            "y": -1.3,
            "t": "Lagos"
          },
          {
            "x": 8.05,
            "y": -1.3,
            "t": "Oyo"
          },
          {
            "x": 15.05,
            "y": -1.3,
            "t": "Ondo"
          }
        ]
      },
      "mark": {
        "type": "text",
        "align": "left",
        "font": "Georgia",
        "fontSize": 16,
        "fontWeight": "bold",
        "color": "#0B2530"
      },
      "encoding": {
        "x": {
          "field": "x",
          "type": "quantitative",
          "scale": {
            "domain": [
              -0.7,
              20.7
            ]
          },
          "axis": null
        },
        "y": {
          "field": "y",
          "type": "quantitative",
          "scale": {
            "domain": [
              -1.7,
              6.4
            ],
            "reverse": true
          },
          "axis": null
        },
        "text": {
          "field": "t",
          "type": "nominal"
        }
      }
    },
    {
      "data": {
        "values": [
          {
            "x": -0.2,
            "y": 5.95,
            "c": "#B4281E",
            "s": "#B4281E",
            "t": "Add public clinics"
          },
          {
            "x": 5.2,
            "y": 5.95,
            "c": "#E8B4AF",
            "s": "#B4281E",
            "t": "Contract private clinics"
          },
          {
            "x": 11.6,
            "y": 5.95,
            "c": "#C9D3D8",
            "s": "#FFFFFF",
            "t": "No action now"
          },
          {
            "x": 15.6,
            "y": 5.95,
            "c": "#E6ECEF",
            "s": "#FFFFFF",
            "t": "Outside selection"
          }
        ]
      },
      "layer": [
        {
          "mark": {
            "type": "point",
            "shape": "M0,-1L0.866,-0.5L0.866,0.5L0,1L-0.866,0.5L-0.866,-0.5Z",
            "filled": true,
            "size": 150,
            "strokeWidth": 1.5
          },
          "encoding": {
            "x": {
              "field": "x",
              "type": "quantitative",
              "scale": {
                "domain": [
                  -0.7,
                  20.7
                ]
              },
              "axis": null
            },
            "y": {
              "field": "y",
              "type": "quantitative",
              "scale": {
                "domain": [
                  -1.7,
                  6.4
                ],
                "reverse": true
              },
              "axis": null
            },
            "color": {
              "field": "c",
              "type": "nominal",
              "scale": null,
              "legend": null
            },
            "stroke": {
              "field": "s",
              "type": "nominal",
              "scale": null,
              "legend": null
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "dx": 10,
            "font": "Segoe UI",
            "fontSize": 10,
            "color": "#51656F"
          },
          "encoding": {
            "x": {
              "field": "x",
              "type": "quantitative",
              "scale": {
                "domain": [
                  -0.7,
                  20.7
                ]
              },
              "axis": null
            },
            "y": {
              "field": "y",
              "type": "quantitative",
              "scale": {
                "domain": [
                  -1.7,
                  6.4
                ],
                "reverse": true
              },
              "axis": null
            },
            "text": {
              "field": "t",
              "type": "nominal"
            }
          }
        }
      ]
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false
    }
  }
}'

